output_text:
[
  {
    "id": "return_cart_at_checkout",
    "text": "Shoppers are obliged to return the cart at the checkout/cart-return cell before leaving the store.",
    "abstraction": {
      "state_properties": {
        "checkout_return_cell": "at(0,1)",
        "cart_parked_at_checkout": "cartAt(0,1)",
        "not_holding_cart": {
          "not": "hasCart"
        },
        "checkout_cart_returned": {
          "and": [
            "cart_parked_at_checkout",
            "not_holding_cart"
          ]
        }
      },
      "events": {
        "return_cart_at_checkout": {
          "pre": {
            "and": [
              "checkout_return_cell",
              "hasCart",
              "LEAVE_CART"
            ]
          },
          "post": "checkout_cart_returned"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "return_cart_at_checkout"
    }
  },
  {
    "id": "no_exit_with_cart",
    "text": "Shoppers are prohibited from exiting the supermarket while still holding or pushing a cart.",
    "abstraction": {
      "state_properties": {
        "exit_cell": "at(9,5)",
        "holding_cart": "hasCart"
      },
      "events": {
        "exit_with_cart": {
          "pre": {
            "and": [
              "EXIT",
              "exit_cell",
              "holding_cart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_cart"
    }
  },
  {
    "id": "cart_only_left_at_checkout",
    "text": "Shoppers may put down a cart only at the designated checkout/cart-return location.",
    "abstraction": {
      "state_properties": {
        "designated_cart_return": "at(0,1)",
        "outside_designated_cart_return": {
          "not": "designated_cart_return"
        }
      },
      "events": {
        "leave_cart_elsewhere": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "outside_designated_cart_return"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "leave_cart_elsewhere"
    }
  },
  {
    "id": "must_take_entrance_cart",
    "text": "Shoppers are obliged to take the available entrance cart before doing their shopping.",
    "abstraction": {
      "state_properties": {
        "entrance_cart_cell": "at(1,5)",
        "entrance_cart_waiting": "cartAt(1,5)"
      },
      "events": {
        "take_entrance_cart": {
          "pre": {
            "and": [
              "entrance_cart_cell",
              "entrance_cart_waiting",
              "PICKUP_CART"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "take_entrance_cart"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "Shoppers are prohibited from picking up merchandise unless they currently have a cart.",
    "abstraction": {
      "state_properties": {
        "cartless": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "cartless"
            ]
          },
          "post": null
        },
        "cart_item_pickup": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "hasCart"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying_merchandise",
    "text": "Shoppers are prohibited from carrying store items by hand rather than putting them in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_item_by_hand": "handFull",
        "properly_using_cart_for_items": {
          "and": [
            "hasCart",
            {
              "not": "handFull"
            }
          ]
        }
      },
      "events": {
        "become_hand_full": {
          "pre": {
            "not": "handFull"
          },
          "post": "handFull"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_item_by_hand"
    }
  },
  {
    "id": "pickup_only_at_product_access_cells",
    "text": "Shelf interactions are allowed only at recognized product-access cells, abstracting over the lower and upper aisle approaches to the same shelves.",
    "abstraction": {
      "state_properties": {
        "apple_access": {
          "or": [
            "at(1,3)",
            "at(2,4)"
          ]
        },
        "bread_access": {
          "or": [
            "at(3,2)",
            "at(3,4)"
          ]
        },
        "milk_access": {
          "or": [
            "at(5,2)",
            "at(5,4)"
          ]
        },
        "eggs_access": {
          "or": [
            "at(6,2)",
            "at(6,4)"
          ]
        },
        "recognized_product_access": {
          "or": [
            "apple_access",
            "bread_access",
            "milk_access",
            "eggs_access"
          ]
        }
      },
      "events": {
        "pickup_at_recognized_product_access": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              "recognized_product_access"
            ]
          },
          "post": null
        },
        "pickup_outside_product_access": {
          "pre": {
            "and": [
              "PICKUP_ITEM",
              {
                "not": "recognized_product_access"
              }
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "pickup_outside_product_access"
    }
  },
  {
    "id": "no_carts_in_exit_area",
    "text": "Shopping carts are prohibited in the customer-only exit corridors, so shoppers must leave the cart before taking a route to the exit.",
    "abstraction": {
      "state_properties": {
        "customer_only_exit_area": {
          "or": [
            "at(7,2)",
            "at(8,2)",
            "at(7,3)",
            "at(8,3)",
            "at(9,3)",
            "at(7,4)",
            "at(8,4)",
            "at(9,4)",
            "at(7,5)",
            "at(8,5)",
            "at(9,5)"
          ]
        },
        "cart_in_customer_only_exit_area": {
          "and": [
            "hasCart",
            "customer_only_exit_area"
          ]
        }
      },
      "events": {
        "enter_exit_area_with_cart": {
          "pre": "cart_in_customer_only_exit_area",
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cart_in_customer_only_exit_area"
    }
  }
]
